package in.amanahpay.config;
import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.web.cors.*;import org.springframework.web.filter.CorsFilter;import java.util.*;
@Configuration public class CorsConfig {@Bean CorsFilter corsFilter(@Value("${CORS_ORIGINS:http://localhost:5173}")String origins){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(Arrays.asList(origins.split(",")));c.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type","Accept"));c.setAllowCredentials(true);UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return new CorsFilter(s);}}
